"""Current investor-facing forward-credit evidence, sourced from completed runs."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
TITLE='Appendix. Forward-taught optimizer transport'

def pages():
    path=ROOT/'investment/forward_credit_evidence_20261011.json'
    if not path.exists():return []
    d=json.loads(path.read_text());assert d['status']=='completed'
    for name,digest in d['completed_evidence_sha256'].items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest
    m=d['metrics'];f=d['fresh'];c=d['controller'];e=d['execution']
    accuracy=[[name.replace('_',' '),f"{value:.9e}"] for name,value in f['mse'].items() if name in ['static_full','reference_full','transport_diagonal']]
    first=[('h1',TITLE),('p','One shared native forward response supplies feature geometry and supervised feedback for many candidate routes. The credit model transports their alternative lexical parameters and Adam moments instead of fitting every alternative independently. Full factual correction preserves the issued route-gradient expectation.'),('h2','Prospective fresh-prefix accuracy'),('table',(['Credit predictor','Contrast MSE'],accuracy,[82,85])),('p',f"Fixed diagonal transport reduces error by {m['credit_error_static_reduction_pct']:.1f}% versus static credit and {m['credit_error_reference_reduction_pct']:.1f}% versus reference-only credit. All eight fresh prefixes improve; registered paired-prefix bootstrap 95% improvement intervals are positive."),('small','Eight new FineWeb TRAIN-tail prefixes, 64 context / 48 future targets, 65 issued hard-write candidates. Source fixed native two-layer model, 50,257 GPT-2 token classes; 64-dimensional online lexical Adam learners. One observed future per prefix, disjoint smoke, rule frozen before new labels. Prospective component calibration, no public DEV/TEST or native-carrier quality claim.'),('h2','A connected controller receives a better signal'),('p',f"In a fixed {c['parameters']:,}-parameter route controller, transport reduces conditional action-gradient noise by {m['credit_controller_variance_reduction_pct']:.1f}% versus static credit. Expected parameter gradients match the exact route objective within {c['max_mean_error']:.2e}. Four earlier prefixes; this measures action noise, not variation across future sequences or optimization speed."),('p','The working prototype already carries selected keys, lexical parameters and optimizer state between route-learning windows. Early 512-target controller fits have no confirmed held-out task gain. The next decisive test is better held-out prediction per total learning cost.')]
    work=[]
    for r in e['summaries']:
        work.append([r['arm'].replace('_',' '),f"{r['whole_pipeline_wall_s']:.3f}",f"{r['whole_pipeline_supported_flops']/1e9:.3f}",f"{r['whole_pipeline_supported_flops']/192/1e6:.3f}"])
    second=[('h2','Matched corrected-credit acquisition'),('table',(['Method','Whole seconds','Whole GFLOPs','MFLOPs / target'],work,[54,33,39,41])),('p',f"Transport plus exact factual correction runs {m['credit_pipeline_speedup']:.2f}x faster with {m['credit_supported_work_reduction_pct']:.1f}% fewer supported operations than exhaustive independent alternative learning. Both include the same native context, candidate discovery and normalized outputs. Transport predicts the alternatives approximately; observed factual/reference losses are exact."),('small','Four earlier prefixes, 48 targets each, three rotated timing repeats. Median execution per prefix plus common acquisition; 192 scored targets per representative pipeline. All keys/vocabulary work, optimizer state, selected actual learner, copies and correction paid. Unsupported scalar/special/optimizer arithmetic omitted from supported FLOPs and included in wall. Repeated measurements, exact-oracle acquisition, source pretraining and contracts/smokes additional. Acquisition economy, not matched-quality task-learning speed or hardware energy.'),('h2','Future learning changes the right route'),('p','In the native 48-target probe, direct addressed-output effects vanish while learner-state effects persist. Three of four prefixes have later cumulative effects opposing the first eight targets; one offsets 30.1% of the initial loss increase. The best route changes between 8- and 48-target objectives in three of four all-route calibration prefixes.'),('p','Credit must carry learning influence as well as physical message decay. Optimizer transport and a connected downstream critic provide complementary ways to represent that influence.')]
    third=[('h2','Conditional platform potential'),('bullets',['Economical continual adaptation as language, processes and environments change.','Local industrial and embodied systems with constrained learning-state budgets.','Reusable credit across routes and modalities, with a sparse asynchronous hardware path.']),('p','These are conditional application and economic implications. Customer adoption requires useful quality, reliability and measured complete deployment cost. Hardware energy, traffic and depth scaling require their own measurements.'),('h2','Compression and depth: the next formal target'),('p','Compress task-relevant influence on future learning/loss, with weights, moments, activations and precision charged. Low-dimensional state does not imply a few-bit or optimal representation. For the restricted head, independent alternatives cost O(WVd), shared reference plus transport O(Vd+Wd). Full-carrier learning has additional cross-layer work.'),('p','Depth errors obey a local amplification-plus-residual recurrence. Connected credit geometry, joint downstream-loss training, long-range anchors and adaptive exact corrections can reduce amplification and local error. Legitimate signal gains must be retained; stability cannot be obtained by discarding useful credit.'),('h2','Promotion gates'),('bullets',['Better held-out prediction per total learning work on the token protocol.','Quality/work curves across data, depth, width and candidate capacity.','Reproducible online application evaluation, then measured target-hardware memory, latency, traffic and energy.']),('small','Evidence and formulas: investment/forward_credit_evidence_20261011.json. Theory: OPTIMIZER_STATE_TRANSPORT_CREDIT, STATE_INFLUENCE_BOUNDARY_CRITIC and LEARNED_DEPTH_CREDIT_REPRESENTATIONS. No pending cell is presented as a result.')]
    followup=ROOT/'experiments/results/credit/curie_route48_transport_20261011_v1_fit.json'
    if not followup.exists():return [first,second,third]
    r=json.loads(followup.read_text());assert r['status']=='completed'
    for name,digest in r['source_sha256'].items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest
    gain=r['comparisons']['transport_over_static'];ci=gain['paired_prefix_bootstrap95']
    rows=[[a['arm'],f"{a['wall_s']:.3f}",f"{a['supported_flops']/1e9:.3f}",f"{a['supported_flops']/1536/1e6:.3f}"] for a in r['fitting']]
    fourth=[('h2','Completed carried 48-target route-learning development'),('p',f"Transport-over-static stochastic expected NLL gain {gain['gain']:+.3e} nats/target; paired-prefix 95% interval [{ci[0]:+.3e}, {ci[1]:+.3e}]. No confirmed utility gain. This diagnoses the fixed 32-update variant; it is not a model-family benchmark verdict."),('table',(['Arm','Fit seconds','Fit GFLOPs','Fit MFLOPs / target'],rows,[54,33,39,41])),('small','One initialization, 32 consecutive 48-target windows (1,536 targets), shared initial controller, 37,377 parameters; source native two-layer model fixed. Key/lexical/Adam state carries during training. Eight fresh private TRAIN-tail scoring prefixes, 64 context / 48 future targets, exact expected issued-route NLL. Public DEV/TEST untouched. Supported FLOPs omit unsupported arithmetic included in wall.'),('p',f"Shared exhaustive scoring: {r['scoring']['wall_s']:.3f}s, {r['scoring']['supported_flops']/1e9:.3f} GFLOPs, {r['scoring']['supported_flops']/384/1e6:.3f} MFLOPs per scored target, 520 independent worlds / 24,960 updates. Whole experiment {r['whole_wall_s']:.3f}s, peak RSS {r['peak_rss_kb']/1024:.1f} MiB; source pretraining and admission checks additional. Standalone inference work was not measured in this development fit."),('p','Static and transport select the same actual action in all 32 training windows, despite different gradients. Exact uniform-to-best route headroom on scoring prefixes is 0.000575–0.004898 nats/target. Both train on carried learner state and score on fresh episode state. Next diagnose this state mismatch and policy movement before another fit; expand to jointly learned multiscale credit only with a causal observed-consequence target.'),('small','Completed source-bound result: experiments/results/credit/curie_route48_transport_20261011_v1_fit.json. No new Transformer/LSTM control, public scoring or energy claim.')]
    learned=ROOT/'experiments/results/credit/curie_forward_credit_predictor_20261011_v1_fit.json'
    if not learned.exists():return [first,second,third,fourth]
    fwd=json.loads(learned.read_text());assert fwd['status']=='completed'
    for name,digest in fwd['source_sha256'].items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest
    means={arm:sum(row['mse'][arm] for row in fwd['rows'])/len(fwd['rows']) for arm in ['zero','corrected','uncorrected']}
    comp=fwd['comparisons']['corrected_over_zero'];lo,hi=comp['paired_prefix_bootstrap95'];st=fwd['stages']
    summary=[[name,f"{stage['wall_s']:.3f}",f"{stage['supported_flops']/1e9:.3f}",f"{stage['supported_flops']/(384 if name=='scoring' else 1536)/1e6:.3f}"] for name,stage in st.items()]
    fifth=[('h2','Connected prefix-only future credit: development result'),('p',f"Fresh route-contrast MSE: zero {means['zero']:.3e}, corrected {means['corrected']:.3e}, uncorrected {means['uncorrected']:.3e}. Corrected prediction is {100*(means['corrected']/means['zero']-1):.1f}% worse than zero; MSE improvement interval [{lo:+.3e}, {hi:+.3e}] is negative. This first predictor fails its predictive gate. Corrected versus uncorrected is inconclusive."),('table',(['Stage','Seconds','GFLOPs','MFLOPs / observed target'],summary,[54,33,39,41])),('small','Acquisition/fitting denominator1,536 observed TRAIN targets (32 prefixes x48); scoring denominator384 targets (8 new prefixes x48). Both critic fits share acquisition/scoring. Ten fixed fitting passes, 320 updates per arm, 54,081 parameters; properly tokenized FineWeb/source native two-layer fixed. Supported work omits unsupported arithmetic included in wall; source pretraining/contracts/smokes additional.'),('p','Training approximate-label error falls33.5% below zero, while mean training/fresh cosine alignment is +0.538/-0.112. This diagnoses a generalization gap. Shared forward labels and an exact observed-route residual train an unbiased squared-risk gradient; the contract checks this algebra, not future predictability.'),('p','Earlier post-observation transport calibration and this prefix-only foresight task are distinct. The next registered data stage reuses32 paid records, adds96 new training prefixes and scores16 fresh prefixes with the model and training rule unchanged. Its result is pending; no depth or task-quality claim is filled in.'),('h2','Warm learner state does not resolve route utility'),('p','Eight reused private scoring prefixes: warm lexical/Adam transport-over-static gain -1.032e-7 nats/target, paired95%[-8.407e-7,+5.365e-7]. Ordinary warm lexical adaptation improves initial-policy mean NLL0.009412; this is not learned-credit utility. Cost111.234s/372.085GF, 595.3MiB peak, same native64-context forward path. No fitting/public scoring/independent confirmation.'),('small','Completed records: curie_forward_credit_predictor_20261011_v1_fit; curie_forward_credit_predictor_diagnosis_20261011_v1; curie_route48_warm_20261011_v1_measure. Next-stage protocol: FORWARD_CREDIT_SCALING_PROTOCOL.md. Depth direction: joint consequence learning, multiscale consistency/anchors, amplification-aware sparse corrections.')]
    scaled=ROOT/'experiments/results/credit/curie_forward_credit_scaling_20261011_v1_fit.json'
    if not scaled.exists():return [first,second,third,fourth,fifth]
    large=json.loads(scaled.read_text());assert large['status']=='completed'
    for name,digest in large['source_sha256'].items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest
    lg=large['comparisons']['corrected_over_zero'];lmean={arm:sum(row['mse'][arm] for row in large['rows'])/len(large['rows']) for arm in ['zero','corrected','uncorrected']}
    sixth=[('h2','Completed unchanged-model future-credit data stage'),('p',f"128 training prefixes /16 new exact-scored private prefixes, same54,081-parameter model, initial seed, learning rate and10fitting passes. Fresh corrected MSE {lmean['corrected']:.3e} versus zero {lmean['zero']:.3e}; corrected-over-zero MSE gain {lg['mean_gain']:+.3e}, paired95%{lg['paired_prefix_bootstrap95']}. Predictive gate: {large['predictive_gate']}. This is private development evidence; the32/128 cohorts differ, so their comparison is unpaired."),('p','32 acquisition records are reused and96 newly acquired. Report incremental plus inherited acquisition work; earlier critic fitting/diagnostics, source pretraining/contracts/smokes are additional. Final checkpoint only, no held-out selection. Native source frozen/two-layer, cold lexical state, no actor or full-native training.'),('table',(['Stage','Seconds','GFLOPs','MFLOPs / observed target'],[[name,f"{stage['wall_s']:.3f}",f"{stage['supported_flops']/1e9:.3f}",f"{stage['supported_flops']/(768 if name=='scoring' else 6144)/1e6:.3f}"] for name,stage in large['stages'].items()],[54,33,39,41])),('p',f"Inherited acquisition: {large['stages']['acquisition']['inherited_wall_s']:.3f}s/{large['stages']['acquisition']['inherited_supported_flops']/1e9:.3f}GFLOPs, additional to table incremental work. Whole new stage {large['wall_s']:.3f}s; peak RSS {large['peak_rss_kb']/1024:.1f}MiB. Acquisition/fitting denominator6,144 observed TRAIN targets, scoring768; supported arithmetic convention unchanged."),('h2','Depth learning: forward probes and joint error structure'),('p','Forward responses supply backward-projection teaching targets by reciprocity. Isotropic probe risk equals cotangent squared error; residual projection correction has the exact mean, but one Rademacher probe in n dimensions has variance(n-1) times residual squared norm. Connected predictors and amplification-aware sparse audits must reduce this burden. Joint depth learning should also reduce transported coherent bias and harmful cross-layer error covariance; local MSE alone does not optimize those terms.'),('small','Completed data-stage result: curie_forward_credit_scaling_20261011_v1_fit.json. Theory: DEPTH_CREDIT_FROM_FORWARD_PROBES and LEARNED_DEPTH_CREDIT_REPRESENTATIONS. Data scaling is not depth scaling or prediction-quality-per-work superiority.')]
    fifth=[(kind, value.replace('Its result is pending; no depth or task-quality claim is filled in.','The completed result is reported in the next section.')) if isinstance(value,str) else (kind,value) for kind,value in fifth]
    return [first,second,third,fourth,fifth,sixth]
